   133→        }
   134→        if ($now->gt($endTime)) {
   135→            return response()->json(['success' => false, 'message' => 'Absensi sudah ditutup. Kelas telah selesai pada ' . $endTime->format('H:i') . ' WIB.'], 422);
   136→        }
