   144→        $hadirIds = array_map('intval', $data['hadir_ids'] ?? []);
   145→
   146→        // Collect all student IDs currently shown (from class_students + fallbacks)
   147→        $studentIds = DB::table('class_students')
   148→            ->where('class_id', $schedule->kelas_id)
   149→            ->pluck('student_id')
   150→            ->toArray();
